#!/usr/bin/env python3
"""
Round 186o (culprits), 5 October 2026. Needs round 185o.

Nine more holiday corporatizers; the row's title and note.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 186o (5 October)\n\nNeeds round 185o (guards on its heading). Tiles patch round186o_tiles.py\nbeside it. No app.js?v= bump.\n\n- More holiday corporatizers (asked: entities that corporatized holidays, not\n  sales events). Nine added to tiles holidays/culprits.geojson (now 21), each\n  with its source in the box: Federated Department Stores (Fred Lazarus Jr.\n  had Thanksgiving moved in 1939 for Christmas shopping), Morozoff (1936) and\n  Mary's Chocolate (1958) for Valentine's Day chocolate in Japan, Edgar's\n  Department Store (first shop Santa, Brockton 1890), Dictaphone and Young &\n  Rubicam (devised Secretaries Day, 1952), the Gambrinus Company and Grupo\n  Modelo (Cinco de Mayo as a beer day in the US), and Florists' Telegraph\n  Delivery (Mother's Day flowers; offered Anna Jarvis a commission).\n- Each is placed at a city point from Natural Earth's populated places;\n  Brockton, which Natural Earth lacks, from the US-Cities-Database on GitHub.\n  The box says which city and why.\n- The row's title now says compiled from Wikipedia, histories and reporting,\n  and its note lists the additions.\n"]


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round186o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 185o" not in h.read_text(encoding="utf-8"):
        sys.exit("round186o: round 185o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round186o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round186o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round186o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
